SourceCode.Declaration:
/// <summary>
/// One unit a quantity can be entered in: 1 UnitId = Factor ToUnit. Decimals is the unit's own precision.
/// </summary>
[DataContractAttribute]
class HSMobileOpsItemUnitRow
{
    str unitId;
    real factor;
    int decimals;

}

Method.Source:
[DataMemberAttribute('UnitId')]
public str parmUnitId(str _value = unitId)
{
    unitId = _value;
    return unitId;
}

[DataMemberAttribute('Factor')]
public real parmFactor(real _value = factor)
{
    factor = _value;
    return factor;
}

[DataMemberAttribute('Decimals')]
public int parmDecimals(int _value = decimals)
{
    decimals = _value;
    return decimals;
}
